-- 01-supertypes.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

-- Common spine. Every vertex carries identity, tenancy and audit stamps.
-- Indexes are declared on concrete types, not here: an index on a supertype
-- spreads across every child bucket and hides which lookups are actually hot.

CREATE VERTEX TYPE GaosVertex IF NOT EXISTS;
CREATE PROPERTY GaosVertex.id        STRING   (mandatory true, notnull true);
CREATE PROPERTY GaosVertex.tenantId  STRING   (mandatory true, notnull true);
CREATE PROPERTY GaosVertex.createdAt DATETIME (mandatory true, notnull true);
CREATE PROPERTY GaosVertex.updatedAt DATETIME;

-- Edges share a spine too: who created the edge and when, so a rewired
-- dependency graph can be explained after the fact.
CREATE EDGE TYPE GaosEdge IF NOT EXISTS;
CREATE PROPERTY GaosEdge.createdAt DATETIME;
CREATE PROPERTY GaosEdge.createdBy STRING;
